const $=id=>document.getElementById(id);
$('review-filter').addEventListener('change',()=>{let n=0;for(const card of document.querySelectorAll('[data-review]')){card.hidden=$('review-filter').value==='four'&&card.dataset.review!=='four';if(!card.hidden)n++;}$('review-count').textContent=n+' profession reviews';});
function priorities(){const q=$('priority-search').value.toLowerCase().trim(),area=$('priority-area').value,wave=$('priority-wave').value,education=$('priority-education').value;let n=0;for(const card of document.querySelectorAll('[data-area]')){card.hidden=!!((q&&!card.dataset.search.includes(q))||(area&&card.dataset.area!==area)||(wave&&card.dataset.wave!==wave)||(education&&card.dataset.education!==education));if(!card.hidden)n++;}$('priority-count').textContent=n+' priority profile'+(n===1?'':'s');}
for(const id of ['priority-search','priority-area','priority-wave','priority-education'])$(id).addEventListener(id==='priority-search'?'input':'change',priorities);
